body.script:
let curLang='en';
function toggleLang(){
curLang=curLang==='en'?'bn':'en';
document.querySelectorAll('[data-en]').forEach(el=>{el.textContent=curLang==='en'?el.dataset.en:el.dataset.bn});
document.getElementById('langBtn').textContent=curLang==='en'?'বাংলা':'English';
document.documentElement.lang=curLang;
}
function showTab(e,id){document.querySelectorAll('.panel').forEach(p=>p.classList.remove('active'));document.querySelectorAll('.tab').forEach(t=>t.classList.remove('active'));document.getElementById(id).classList.add('active');e.target.classList.add('active');}
function makeupShade(){const tone=document.getElementById('m_tone').value;const type=document.getElementById('m_type').value;const shades={fair:'Ivory / Porcelain',light:'Light Beige',medium:'Natural Beige',tan:'Warm Honey',deep:'Espresso / Deep'};const primer={oily:'Mattifying primer, oil-free foundation',dry:'Hydrating primer, dewy foundation',combo:'Balancing primer, satin finish',normal:'Any primer, natural finish'};document.getElementById('m_res').innerHTML='Foundation Shade: '+shades[tone]+'
Primer: '+primer[type];}
function lipstickRec(){const occ=document.getElementById('m_occ').value;const rec={daily:'Nude pink, dusty rose, mauve',party:'Bold red, berry, fuchsia',bridal:'Classic red or soft pink',festive:'Deep berry, terracotta, gold shimmer'};document.getElementById('m_lip').innerHTML='Recommended: '+rec[occ];}
function makeupBudget(){const b=+document.getElementById('m_budget').value||0;if(!b){document.getElementById('m_bud').innerHTML='Enter budget';return;}const items=[['Foundation',.25],['Lipstick (x2)',.15],['Mascara',.10],['Blush',.10],['Eyeshadow',.15],['Tools',.15],['Skincare',.10]];let h='Budget: '+b+'
';items.forEach(([n,p])=>h+=n+': '+Math.round(b*p)+'
');document.getElementById('m_bud').innerHTML=h;}
function sizeCalc(){const bust=+document.getElementById('c_bust').value,waist=+document.getElementById('c_waist').value,hip=+document.getElementById('c_hip').value;if(!bust||!waist||!hip){document.getElementById('c_size').innerHTML='Enter measurements';return;}let s;if(bust<=32&&waist<=26&&hip<=34)s='XS';else if(bust<=34&&waist<=28&&hip<=36)s='S';else if(bust<=36&&waist<=30&&hip<=38)s='M';else if(bust<=38&&waist<=32&&hip<=40)s='L';else if(bust<=40&&waist<=34&&hip<=42)s='XL';else s='XXL+';document.getElementById('c_size').innerHTML='Your Size: '+s;}
function bodyTips(){const t=document.getElementById('c_body').value;const tips={pear:'A-line skirts, wide-leg pants, boat-neck tops.',apple:'Empire waist, V-necks, flowy tunics.',hourglass:'Wrap dresses, fitted waists, belted outfits.',rectangle:'Peplum tops, ruffles, layered looks.',inverted:'Wide-leg pants, full skirts.'};document.getElementById('c_tips').innerHTML='Tips: '+tips[t];}
function colorMatch(){const c=document.getElementById('c_color').value;const m={red:'black, white, gold',blue:'white, grey, yellow',green:'beige, brown, gold',pink:'grey, white, navy',black:'red, white, gold',white:'any color',yellow:'navy, grey, white',purple:'grey, gold, pink'};document.getElementById('c_match').innerHTML=c+' pairs with: '+m[c];}
function compColor(){const c=document.getElementById('comp_color').value;const m={red:'Green',blue:'Orange/Coral',green:'Red/Maroon',pink:'Teal/Mint',black:'White/Gold',white:'Any bold color',yellow:'Purple',purple:'Yellow/Gold',orange:'Blue/Navy',teal:'Coral/Pink'};document.getElementById('comp_res').innerHTML=c+' pairs best with: '+m[c];}
function clothBudget(){const b=+document.getElementById('c_budget').value||0;if(!b){document.getElementById('c_bud').innerHTML='Enter budget';return;}const items=[['Dresses/Kurtis',.30],['Tops',.20],['Bottoms',.15],['Shoes',.15],['Accessories',.10],['Undergarments',.10]];let h='Wardrobe: '+b+'
';items.forEach(([n,p])=>h+=n+': '+Math.round(b*p)+'
');document.getElementById('c_bud').innerHTML=h;}
function periodCalc(){const lmp=document.getElementById('h_lmp').value;const cycle=+document.getElementById('h_cycle').value||28;if(!lmp){document.getElementById('h_period').innerHTML='Select date';return;}const d=new Date(lmp);const next=new Date(d);next.setDate(d.getDate()+cycle);const ovu=new Date(d);ovu.setDate(d.getDate()+Math.round(cycle/2));const fmt=x=>x.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});document.getElementById('h_period').innerHTML='Next Period: '+fmt(next)+'
Ovulation: '+fmt(ovu);}
function pregCalc(){const lmp=document.getElementById('h_preg').value;if(!lmp){document.getElementById('h_pregres').innerHTML='Select LMP';return;}const d=new Date(lmp);const due=new Date(d);due.setDate(d.getDate()+280);document.getElementById('h_pregres').innerHTML='Due Date: '+due.toLocaleDateString('en-GB',{day:'2-digit',month:'long',year:'numeric'});}
function bmiCalc(){const h=+document.getElementById('h_h').value,w=+document.getElementById('h_w').value;if(!h||!w){document.getElementById('h_bmi').innerHTML='Enter height & weight';return;}const bmi=w/((h/100)**2);let cat=bmi<18.5?'Underweight':bmi<25?'Normal':bmi<30?'Overweight':'Obese';const lo=18.5*(h/100)**2,hi=24.9*(h/100)**2;document.getElementById('h_bmi').innerHTML='BMI: '+bmi.toFixed(1)+' - '+cat+'
Ideal: '+lo.toFixed(1)+'-'+hi.toFixed(1)+' kg';}
function waterCalc(){const w=+document.getElementById('h_w').value||60;document.getElementById('h_water').innerHTML='Daily Water: ~'+(w*0.033).toFixed(2)+' L = '+Math.round((w*0.033)/0.25)+' glasses';}
function calcCalorie(){const age=+document.getElementById('cal_age').value,h=+document.getElementById('cal_h').value,w=+document.getElementById('cal_w').value,act=+document.getElementById('cal_act').value,goal=+document.getElementById('cal_goal').value,gen=document.getElementById('cal_gender').value;if(!age||!h||!w){document.getElementById('cal_res').innerHTML='Enter age, height & weight';return;}let bmr=gen==='female'?(10*w+6.25*h-5*age-161):(10*w+6.25*h-5*age+5);let tdee=bmr*act;let target=tdee+goal;let protein=Math.round(w*1.6),carbs=Math.round(target*0.45/4),fat=Math.round(target*0.30/9);document.getElementById('cal_res').innerHTML='BMR: '+Math.round(bmr)+' kcal
TDEE: '+Math.round(tdee)+' kcal
Daily Target: '+Math.round(target)+' kcal
Protein: '+protein+'g | Carbs: '+carbs+'g | Fat: '+fat+'g';}
if('serviceWorker' in navigator){navigator.serviceWorker.register('sw.js');}
